using System.Buffers.Binary;
using System.Security.Cryptography;
using System.Text.Json;
using MphRead;
using MphRead.Mods.CustomWeapons;
using MphRead.Mods.Network;
using OpenTK.Mathematics;

internal static class CustomReplayClockChecks
{
    internal static int Run(string? output=null)
    {
        int checks=0;string root=Path.GetFullPath(output??Path.Combine(Path.GetTempPath(),"cw12f-clock-"+Guid.NewGuid().ToString("N")));
        void Check(bool ok,string label){if(!ok)throw new InvalidOperationException(label);checks++;}
        void Reject(Action action,string label){try{action();}catch(Exception error)when(error is InvalidDataException or ArgumentException){Check(true,label);return;}throw new InvalidOperationException("Expected rejection: "+label);}
        try
        {
            Directory.CreateDirectory(root);using var f=new CustomReplayStateChecks.Fixture();var context=f.Context;
            var clock=ReplayCustomWeaponFact.Clock(context,3,1002);byte[] expected=new byte[49];expected[0]=250;expected[1]=2;expected[2]=7;BinaryPrimitives.WriteUInt64LittleEndian(expected.AsSpan(5),3);BinaryPrimitives.WriteUInt32LittleEndian(expected.AsSpan(13),1002);SHA256.HashData(context.Bootstrap.CopyBytes()).CopyTo(expected,17);
            Check(ReplayCustomWeaponFact.ClockVersion==2&&clock.CopyBytes().SequenceEqual(expected),"independent49-byte schema250/version2 Clock7 vector with empty body");
            Check(ReplayCustomWeaponFact.TryRead(expected,context,out var decoded)&&decoded!.Kind==ReplayCustomWeaponFactKind.Clock,"strict v2 clock parser");
            void Bad(byte[] bytes,string label)=>Check(!ReplayCustomWeaponFact.TryRead(bytes,context,out _),label);
            for(int n=0;n<49;n++)Bad(expected[..n],"truncated clock "+n);Bad(expected.Concat(new byte[]{0}).ToArray(),"overbody/trailing clock");var nonempty=expected.Concat(new byte[]{0}).ToArray();nonempty[3]=1;Bad(nonempty,"correct-length clock still refuses nonempty body");
            foreach(int offset in new[]{0,1,2,3,17,48}){var bad=(byte[])expected.Clone();bad[offset]^=128;Bad(bad,"clock schema/context mutation "+offset);}var v1=(byte[])expected.Clone();v1[1]=1;Bad(v1,"v1 never accepts Clock7");var boot=ReplayCustomWeaponFact.Bootstrap(context).CopyBytes();Check(boot[1]==1,"existing Bootstrap v1 bytes unchanged");boot[1]=2;Bad(boot,"v2 reserved only for Clock, not Bootstrap");
            var beforeBaseline=new ReplayCustomWeaponState(context);beforeBaseline.Accept(ReplayCustomWeaponFact.Bootstrap(context),1);Reject(()=>beforeBaseline.Accept(ReplayCustomWeaponFact.Clock(context,2,1001),2),"clock cannot replace required baseline2");
            var passive=f.State(baselineFlight:true);var latest=ReplayCustomWeaponFact.Clock(context,passive.Sequence+1,1002);Check(passive.Accept(latest,20)&&!passive.Accept(latest,20),"new clock advances once and exact retry remains inert");var sameWorld=ReplayCustomWeaponFact.Clock(context,passive.Sequence+1,1002);Reject(()=>passive.Accept(sameWorld,21),"new sequence with nonadvancing clock fails closed");
            var delayed=f.State();delayed.Accept(ReplayCustomWeaponFact.Clock(context,delayed.Sequence+1,1010),20);delayed.Accept(ReplayCustomWeaponFact.Launch(context,delayed.Sequence+1,f.Launch()),21);var delayedFlights=new CustomReplicaFlight[256];Check(delayed.World==1010&&delayed.CopyFlights(delayedFlights)==0,"clock-ahead delayed oldworld launch remains expired without resurrection");
            var contactFirst=f.State();contactFirst.Accept(ReplayCustomWeaponFact.Contact(context,contactFirst.Sequence+1,f.World,f.Contact()),20);contactFirst.Accept(ReplayCustomWeaponFact.Clock(context,contactFirst.Sequence+1,1010),21);contactFirst.Accept(ReplayCustomWeaponFact.Launch(context,contactFirst.Sequence+1,f.Launch()),22);Check(contactFirst.CopyFlights(delayedFlights)==0&&contactFirst.TryContact(f.Launch().Identity,out _,out _),"oldworld contact-before-launch tombstone survives intervening quiet clock");
            var independentFrontiers=f.State();independentFrontiers.Accept(ReplayCustomWeaponFact.Clock(context,independentFrontiers.Sequence+1,1010),20);independentFrontiers.Accept(f.Pickup(independentFrontiers.Sequence+1,0,2,1,1002,1100,false),21);Check(independentFrontiers.World==1010&&independentFrontiers.TryPickup(0,out var delayedPickup)&&delayedPickup.Key.Incarnation==2,"pickup own-frontier advance accepted behind later global clock");independentFrontiers.Accept(ReplayCustomWeaponFact.State(context,independentFrontiers.Sequence+1,1002,f.Slots),22);Check(independentFrontiers.World==1010&&!independentFrontiers.Invalidated,"late canonical table advances own frontier without rewinding global clock");
            var recorder=new ReplayRecorder();var stream=new List<byte[]>();recorder.Accepted+=record=>{if(record.Kind==ReplayFactKind.CustomWeapon)stream.Add(record.Payload.ToArray());};
            var match=new MatchStatePacket{MatchId=7,AuthorityEpoch=f.World.Start.AuthorityEpoch,RoomKey="MP3 PROVING GROUND",NextRoomKey="",Mode=(byte)GameMode.Battle,RuleBits=(uint)(MatchModifierFlags.RiftlineM7Available|MatchModifierFlags.PackagedWeaponAvailable)};
            byte[] Snapshot(uint tick,ushort matchId=7,ulong? epoch=null)
            {
                var bytes=new byte[1+SnapshotHeader.Size+PlayerState.Size+NetMatchTimeSync.Size+NetHealthSync.HeaderSize];bytes[0]=(byte)PacketType.Snapshot;
                new SnapshotHeader{MatchId=matchId,AuthorityEpoch=epoch??f.World.Start.AuthorityEpoch,Frame=tick,PlayerCount=1,Rng1=1234,Rng2=5678}.Write(bytes.AsSpan(1));
                new PlayerState{SlotIndex=1,SlotGeneration=5,LifeId=10,Health=99,Flags=PlayerState.FlagActive|PlayerState.FlagSpawned,Facing=Vector3.UnitZ}.Write(bytes.AsSpan(1+SnapshotHeader.Size));BinaryPrimitives.WriteUInt16LittleEndian(bytes.AsSpan(1+SnapshotHeader.Size+PlayerState.Size+NetMatchTimeSync.Size),matchId);return bytes;
            }
            Check(!recorder.TryCaptureCustomWeaponState(out var absent,out var empty)&&absent==null&&empty.Length==0,"unpublished recorder returns no mutable state snapshot");recorder.AcceptMatch(match,1);
            Check(recorder.AcceptCustomWeaponBaseline(context,new(7,f.World.Start.AuthorityEpoch,context.Bootstrap.Packages.MechanicsDigest,1001,8,1),f.Slots,new[]{f.Flight()},10),"actual recorder owns constructed accepted baseline");
            Check(!recorder.TryCaptureCustomWeaponState(out _,out _),"incomplete pickup scope cannot be exported");for(int i=0;i<context.Layout.Count;i++){var item=new CustomPickupItemState(new(context.PickupWorld,context.Layout.Placements[i].SpawnId,1),990,true,0);Check(recorder.AcceptCustomWeaponPickup(i,1001,item,11),"accepted initial pickup "+i);}
            Check(recorder.TryCaptureCustomWeaponState(out var descriptor,out var initialBytes)&&descriptor!=null,"complete current owner exports immutable descriptor/current checkpoint");var initial=ReplayCustomWeaponState.RestoreCheckpointBytes(initialBytes,descriptor!.InspectContext());var initialFlights=new CustomReplicaFlight[256];Check(initial.CopyFlights(initialFlights)==1,"current export owns original midflight anchor");
            long count=recorder.AcceptedCustomWeaponFacts;recorder.AcceptSnapshot(new byte[]{(byte)PacketType.Snapshot},12,1002);recorder.AcceptSnapshot(Snapshot(1002,8),12,1002);recorder.AcceptSnapshot(Snapshot(1002,epoch:f.World.Start.AuthorityEpoch+1),12,1002);recorder.AcceptSnapshot(Snapshot(1002),12,1003);Check(recorder.AcceptedCustomWeaponFacts==count,"malformed/wrong match/wrong epoch/header-tick mismatch emits no clock");
            int nativeTail=1+SnapshotHeader.Size+PlayerState.Size;byte[] complete=Snapshot(1002);
            recorder.AcceptSnapshot(complete.AsSpan(0,1+SnapshotHeader.Size),12,1002);recorder.AcceptSnapshot(complete.AsSpan(0,nativeTail),12,1002);recorder.AcceptSnapshot(complete.AsSpan(0,nativeTail+NetMatchTimeSync.Size),12,1002);
            var nanTime=(byte[])complete.Clone();BinaryPrimitives.WriteSingleLittleEndian(nanTime.AsSpan(nativeTail),float.NaN);recorder.AcceptSnapshot(nanTime,12,1002);
            var badHealth=(byte[])complete.Clone();badHealth[nativeTail+NetMatchTimeSync.Size+2]=255;recorder.AcceptSnapshot(badHealth,12,1002);
            var wrongHealthMatch=(byte[])complete.Clone();BinaryPrimitives.WriteUInt16LittleEndian(wrongHealthMatch.AsSpan(nativeTail+NetMatchTimeSync.Size),8);recorder.AcceptSnapshot(wrongHealthMatch,12,1002);
            Check(recorder.AcceptedCustomWeaponFacts==count,"header-only/missing time or health tail/NaN time/bad health or tail match cannot advance custom clock");
            recorder.AcceptSnapshot(Snapshot(1001),12,1001);recorder.AcceptSnapshot(Snapshot(1000),12,1000);Check(recorder.AcceptedCustomWeaponFacts==count,"duplicate and older authority snapshot clocks are suppressed");
            recorder.AcceptSnapshot(Snapshot(1004),20,1004);Check(recorder.AcceptedCustomWeaponFacts==count+1&&stream[^1][1]==2&&stream[^1][2]==7,"only advancing valid native snapshot emits accepted Clock v2");
            Check(recorder.TryCaptureCustomWeaponState(out var midDescriptor,out var midBytes),"recorder exports current quiet midflight state");var middle=ReplayCustomWeaponState.RestoreCheckpointBytes(midBytes,midDescriptor!.InspectContext());var flights=new CustomReplicaFlight[256];Check(middle.World==1004&&middle.CopyFlights(flights)==1&&flights[0].Position==initialFlights[0].Position+initialFlights[0].Velocity*3,"quiet snapshot clock advances original per-tick anchor without relabelling baseline");
            recorder.AcceptSnapshot(Snapshot(1010),21,1010);Check(recorder.TryCaptureCustomWeaponState(out var endDescriptor,out var endBytes),"quiet postexpiry current state remains exportable");var end=ReplayCustomWeaponState.RestoreCheckpointBytes(endBytes,endDescriptor!.InspectContext());Check(end.CopyFlights(flights)==0&&end.World==1010,"quiet snapshots alone expire projectile without state/action changes");
            for(int i=0;i<8;i++){initial.TrySlot(i,out var x);end.TrySlot(i,out var y);Check(x==y,"clock does not simulate ammo/inventory/native health slot "+i);}for(int i=0;i<context.Layout.Count;i++){initial.TryPickup(i,out var x);end.TryPickup(i,out var y);Check(x==y,"clock does not simulate pickup respawn "+i);}
            Check(initial.CaptureCheckpointBytes().SequenceEqual(initialBytes)&&middle.CaptureCheckpointBytes().SequenceEqual(midBytes),"previous exported snapshots remain stable after recorder advancement");recorder.RetireCustomWeaponFacts();Check(!recorder.TryCaptureCustomWeaponState(out _,out _)&&middle.CaptureCheckpointBytes().SequenceEqual(midBytes),"retire clears current owner while exported checkpoint remains independent");recorder.Reset();Check(recorder.AcceptedCustomWeaponFacts==0&&!recorder.CustomWeaponCaptureFailed&&!recorder.TryCaptureCustomWeaponState(out _,out _),"reset clears owner/count/failure together");
            var failed=new ReplayRecorder();failed.AcceptMatch(match,1);failed.AcceptCustomWeaponBaseline(context,new(7,f.World.Start.AuthorityEpoch,context.Bootstrap.Packages.MechanicsDigest,1001,8,0),f.Slots,Array.Empty<CustomReplicaFlight>(),10);for(int i=0;i<context.Layout.Count;i++)failed.AcceptCustomWeaponPickup(i,1001,new(new(context.PickupWorld,context.Layout.Placements[i].SpawnId,1),990,true,0),11);
            failed.Accepted+=record=>{if(record.Kind==ReplayFactKind.CustomWeapon)throw new IOException("constructed clock sink failure");};failed.AcceptSnapshot(Snapshot(1002),20,1002);Check(failed.CustomWeaponCaptureFailed&&!failed.TryCaptureCustomWeaponState(out _,out _),"clock observer failure is contained and closes export of unpublished owner");long failedCount=failed.AcceptedCustomWeaponFacts;failed.AcceptSnapshot(Snapshot(1003),21,1003);Check(failed.AcceptedCustomWeaponFacts==failedCount,"observer failure suppresses later custom clock publication");failed.Reset();
            File.WriteAllBytes(Path.Combine(root,"clock.bin"),expected);File.WriteAllBytes(Path.Combine(root,"current-midflight.cwrs"),midBytes);File.WriteAllText(Path.Combine(root,"results.json"),JsonSerializer.Serialize(new{checks,scope="Constructed accepted native snapshot clocks/current-owner exports only; no RNG, ammo, pickup, health simulation or custom replay playback claim."}));Console.WriteLine($"PASS {checks} custom replay snapshot clock/current-owner checks");return 0;
        }
        catch(Exception error){Console.Error.WriteLine("CUSTOM REPLAY CLOCK FAIL "+error);return 1;}
    }
}
